     8	import Foundation
     9	
    10	nonisolated enum DueStatus {
    11	    case overdue
    12	    case dueToday
    13	}
    14	
    15	nonisolated func dueStatus(
    16	    dueDateComponents: DateComponents?,
    17	    isCompleted: Bool,
    18	    now: Date,
    19	    calendar: Calendar) -> DueStatus? {
    20	    guard !isCompleted, let dueDateComponents, let dueDate = calendar.date(from: dueDateComponents) else {
    21	        return nil
    22	    }
    23	    let startOfToday = calendar.startOfDay(for: now)
    24	    if dueDate < startOfToday {
    25	        return .overdue
    26	    }
    27	    if calendar.isDate(dueDate, inSameDayAs: startOfToday) {
    28	        return .dueToday
    29	    }
    30	    return nil
    31	}
