     7	
     8	import EventKit
     9	import Observation
    10	#if os(iOS)
    11	    import UIKit
    12	#elseif os(macOS)
    13	    import AppKit
    14	#endif
    15	
    16	enum ReminderAccessStatus {
    17	    case notDetermined
    18	    case denied
    19	    case authorized
    20	
    21	    // MARK: Lifecycle
    22	
    23	    init(_ status: EKAuthorizationStatus) {
    24	        switch status {
    25	        case .notDetermined:
    26	            self = .notDetermined
    27	        case .denied, .restricted, .writeOnly:
    28	            self = .denied
    29	        case .authorized, .fullAccess:
    30	            self = .authorized
    31	        @unknown default:
    32	            self = .denied
    33	        }
    34	    }
    35	}
    36	
    37	@MainActor
    38	@Observable
    39	final class ReminderStore {
    40	    // MARK: Internal
    41	
    42	    let eventStore = EKEventStore()
    43	
    44	    private(set) var accessStatus = ReminderAccessStatus.notDetermined
    45	    private(set) var reminders: [EKReminder] = []
    46	
    47	    func load() async {
    48	        if EKEventStore.authorizationStatus(for: .reminder) == .notDetermined {
    49	            await waitUntilActive()
    50	            guard !isRequestingAccess else {
    51	                return
    52	            }
    53	            isRequestingAccess = true
    54	            _ = await requestFullAccess()
    55	            isRequestingAccess = false
    56	        }
    57	        accessStatus = ReminderAccessStatus(EKEventStore.authorizationStatus(for: .reminder))
    58	        guard accessStatus == .authorized else {
    59	            reminders = []
    60	            return
    61	        }
    62	        eventStore.reset()
    63	        let predicate = eventStore.predicateForIncompleteReminders(
    64	            withDueDateStarting: nil,
    65	            ending: nil,
    66	            calendars: nil)
    67	        reminders = await fetchReminders(matching: predicate)
    68	    }
    69	
    70	    // MARK: Private
    71	
    72	    private static var didBecomeActiveNotification: Notification.Name {
    73	        #if os(iOS)
    74	            UIApplication.didBecomeActiveNotification
    75	        #elseif os(macOS)
    76	            NSApplication.didBecomeActiveNotification
    77	        #endif
    78	    }
    79	
    80	    private static var isActive: Bool {
    81	        #if os(iOS)
    82	            UIApplication.shared.applicationState == .active
    83	        #elseif os(macOS)
    84	            NSApplication.shared.isActive
    85	        #endif
    86	    }
    87	
    88	    private var isRequestingAccess = false
    89	
    90	    private func fetchReminders(matching predicate: NSPredicate) async -> [EKReminder] {
    91	        nonisolated(unsafe) var result: [EKReminder] = []
    92	        await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
    93	            eventStore.fetchReminders(matching: predicate) { reminders in
    94	                result = reminders ?? []
    95	                continuation.resume()
    96	            }
    97	        }
    98	        return result
    99	    }
   100	
   101	    private func requestFullAccess() async -> Bool {
   102	        await withCheckedContinuation { continuation in
   103	            eventStore.requestFullAccessToReminders { granted, _ in
   104	                continuation.resume(returning: granted)
   105	            }
   106	        }
   107	    }
   108	
   109	    private func waitUntilActive() async {
   110	        guard !Self.isActive else {
   111	            return
   112	        }
   113	        for await _ in NotificationCenter.default.notifications(named: Self.didBecomeActiveNotification) {
   114	            break
   115	        }
   116	    }
   117	}
